import{_ as s,l as i,o,c as n,v as p,p as d,x as t,d as l,i as c,S as E,b as e}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"稠密升级到 MoE","description":"","frontmatter":{"title":"稠密升级到 MoE","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dense-to-moe-upcycling.md","filePath":"llm/dense-to-moe-upcycling.md","lastUpdated":1789023840000}'),m={name:"llm/dense-to-moe-upcycling.md"};function h(u,a,F,A,B,g){const r=i("Mermaid");return o(),n("div",null,[a[1]||(a[1]=p('<h1 id="稠密升级到-moe" tabindex="-1">稠密升级到 MoE <a class="header-anchor" href="#稠密升级到-moe" aria-label="Permalink to &quot;稠密升级到 MoE&quot;">​</a></h1><div class="epigraph"><p>把已训好的 FFN 复制成若干专家、再长出路由器，稠密计算最优的检查点可以变成稀疏容量更大的模型，而不从随机 MoE 重买压熵段。</p><footer>—— Komatsuzaki et al., Sparse Upcycling, 2022；路由稳定性见 Fedus et al., Switch Transformer；主干路由器梯度课不重推</footer></div><p><a href="/llm/model-growth-depth-upscaling">上一课</a>把层沿深度插进去。缺口是沿<strong>专家</strong>轴长：Komatsuzaki 等人的 sparse upcycling 从稠密检查点复制 FFN 为 \\(E\\) 份专家，随机或零初始化路由器，再继续训。总参数涨、每 token FLOPs 可保持近稠密（top-1 / top-2）。本课写升级时的恒等条件与负载均衡，不重写 <a href="/llm/moe-router-gradient">路由器梯度</a> 或 Switch 的容量因子。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>随机 MoE 要从零学路由与专家专项，压熵段贵且易塌缩到少数专家。升级希望：起步时无论路由到哪，FFN 近似旧稠密 FFN，函数连续。复制权重做到这一点；路由器若输出均匀，每个专家都像旧 FFN，模型先是「带噪声的稠密」，再拉开专项。路由器若一开始就尖锐，部分专家吃全部 token，其余冻死——冷专家踩 Adam \\(\\varepsilon\\) 巨步，热专家过拟合。</p><p>每 token FLOPs 与 \\(N_{\\mathrm{total}}\\) 脱钩。Chinchilla / 推理最优的账要用 <strong>激活参数</strong> 或 <strong>每 token FLOPs</strong>，不能把专家参数加总当 \\(N\\) 去套 20 token / 参数。这是形状课留下的 MoE 缺口。</p><p><span class="marginnote">复制后的专家完全相关。后续训练必须有足够数据与均衡项把它们推开。数据不够时，升级只是把存盘变大，推理若 top-2 还会更贵。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>步骤：</p><ol><li>选定哪些层升级（常是每隔一层 FFN，注意力保持稠密）。</li><li>专家权重复制自稠密 FFN；路由器小初始化，使 logits 近 0、门控近均匀。</li><li>打开负载均衡与 router z-loss（主干已有），系数先保守。</li><li>短 warmup，监控专家负载熵、容量 drop、以及总线 RMS 相对升级前连续。</li><li>代理上用加大 \\(\\eta\\) 看是否出现路由锁死（Wortsman 式应力）。</li></ol><p>推理账：部署若 top-2，激活 FLOPs 高于原稠密，推理最优可能并不偏向这个升级后的模型。训练期省的是相对「从零训同容量 MoE」，不是相对「停在稠密」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>均匀路由 + 复制专家 = 旧 FFN 的期望，方差来自 Bernoulli 选择。均衡项迫使 token 分散，专家梯度开始正交化。锁死是 <a href="/llm/attention-logit-growth">注意力熵塌缩</a> 在路由 softmax 上的兄弟：熵塌后多数专家 \\(v\\) 极小，偶发大梯度造成尖峰。router z-loss 与 cap 的分工同前：钉绝对尺度 vs 有界。不要只抄稠密上的词表 z-loss 系数到路由器上。</p><p>与深度扩展同时做（又插层又升级）归因极难，应串行：先稳一种生长。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Expert-choice 与 dropless 改容量语义，升级时的「均匀起步」假设要重验。下一课离开生长，进入<strong>多模型合成</strong>：SLERP / TIES / DARE，对象是已有的多个权重，而不是一个稠密爸爸。</p>',16)),(o(),d(E,null,{default:t(()=>[c(r,{id:"mermaid-70",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E7%A8%A0%E5%AF%86%20FFN%22%5D%20--%3E%20CPY%5B%22%E5%A4%8D%E5%88%B6%E4%B8%BA%20E%20%E4%B8%AA%E4%B8%93%E5%AE%B6%22%5D%0A%20%20CPY%20--%3E%20R%5B%22%E5%B0%8F%E5%88%9D%E5%A7%8B%E5%8C%96%E8%B7%AF%E7%94%B1%E5%99%A8%3A%20%E8%BF%91%E5%9D%87%E5%8C%80%22%5D%0A%20%20R%20--%3E%20BAL%5B%22%E5%9D%87%E8%A1%A1%20%2B%20router%20z-loss%22%5D%0A%20%20BAL%20--%3E%20SPLIT%5B%22%E4%B8%93%E5%AE%B6%E4%B8%93%E9%A1%B9%E5%8C%96%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"小结",tabindex:"-1"},[l("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=e("ul",null,[e("li",null,"Sparse upcycling 复制 FFN、均匀起步路由，避免从零 MoE 重买压熵。"),e("li",null,"账本用每 token FLOPs / 激活参数，禁止把专家总数套进稠密 Chinchilla。"),e("li",null,"路由熵塌缩与冷专家 \\(\\varepsilon\\) 巨步是主要炸因；先代理应力。"),e("li",null,"与插层生长串行，不要一次变两种形状。"),e("li",null,"出处：Komatsuzaki et al., 2022；Switch / ST-MoE 的路由稳定项。")],-1))])}const P=s(m,[["render",h]]);export{k as __pageData,P as default};
